from pathlib import Path
p=Path('index.html')
s=p.read_text()
helper="function weightMetric(lb){let n=Number(lb);if(!Number.isFinite(n)||n<=0)return '';let kg=n*0.45359237;return kg<1?`${Math.round(kg*1000)} g`:`${kg.toFixed(2)} kg`}"
# Clean up duplicate helper safely if two guarded workflows ever raced.
while s.count(helper)>1:
    s=s.replace(helper+'\n'+helper,helper,1)
# If the event form is already patched, only perform cleanup and stop.
start=s.index('function eventForm(type,d,o=null){')
end=s.index('\nfunction mapv(d){',start)
current=s[start:end]
if 'weightLb' not in current:
    new=r'''function eventForm(type,d,o=null){type=o?.type||type||'catch';let day=currentDay(d),wid=o?.waterId||day?.waterId||d.waters[0]?.id||'',as=activeSpotSession(day),sid=o?.spotId||as?.spotId||'',weightLb=o?.weightLb||'';show(o?`${et(type)} bearbeiten`:`Neuer Eintrag · ${et(type)}`,`<form id="ef" class="form"><div class="notice"><b>${ei(type)} ${et(type)}</b> · Wetter wird beim Speichern automatisch aktualisiert.</div><button class="btn secondary full" type="button" id="eventWeather">🌤️ Wetter jetzt aktualisieren</button><div id="eventWeatherPreview">${weatherHTML(o?.weather||null)}</div><div class="field"><label>Gewässer</label><select name="waterId" required>${d.waters.map(w=>`<option value="${w.id}" ${w.id===wid?'selected':''}>${esc(w.name)}</option>`).join('')}</select></div><div class="field"><label>Spot</label><select name="spotId"><option value="">– optional –</option>${d.spots.filter(s=>!wid||s.waterId===wid).map(s=>`<option value="${s.id}" ${s.id===sid?'selected':''}>${esc(spotLabel(d,s.id))}</option>`).join('')}</select></div>${['catch','bite','lost','follow'].includes(type)?selectField('species','Fischart',['Schwarzbarsch','Barsch','Zander','Hecht','Karpfen','Forelle'],o?.species||'Schwarzbarsch'):''}${['catch','lost'].includes(type)?field('length','Länge cm',o?.length||'','number','step="0.1" min="0"'):''}${type==='catch'?`<div class="field"><label>Gewicht lbs</label><input name="weightLb" type="number" step="0.01" min="0" value="${esc(weightLb)}" inputmode="decimal"><small class="muted" id="weightMetric">${weightMetric(weightLb)?'('+weightMetric(weightLb)+')':''}</small></div>`:''}${['catch','bite','lost','follow'].includes(type)?selectField('lure','Köder',['Chatterbait','Jig','Gummifisch','Wobbler','Spinner','Crankbait','Topwater','Texas Rig','Carolina Rig','Dropshot','Jerkbait','Sonstiger'],o?.lure||''):''}${area('notes','Notizen',o?.notes||'')}<div class="field"><label>Fotos</label><input name="photos" type="file" accept="image/*" multiple></div><button class="btn full">Speichern</button>${o?'<button class="btn danger full" type="button" id="edelete">Löschen</button>':''}</form>`);let snap=o?.weather||null;let wi=$('[name=weightLb]');if(wi)wi.oninput=()=>{$('#weightMetric').textContent=weightMetric(wi.value)?`(${weightMetric(wi.value)})`:''};$('#eventWeather').onclick=async()=>{try{snap=await freshWeather();$('#eventWeatherPreview').innerHTML=weatherHTML(snap)}catch{alert('Wetter gerade nicht erreichbar.')}};$('#ef').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),pp=await imgs(e.target.photos.files),wl=f.get('weightLb')||'';if(wl&&(!Number.isFinite(Number(wl))||Number(wl)<0)){alert('Bitte ein gültiges Gewicht eingeben.');return}if(!snap){try{snap=await freshWeather()}catch{}}let x={...(o||{}),id:o?.id||crypto.randomUUID(),type,waterId:f.get('waterId'),spotId:f.get('spotId'),dayId:o?.dayId||day?.id||'',species:f.get('species')||'',length:f.get('length')||'',weightLb:wl,weightKg:wl?Number(wl)*0.45359237:null,lure:f.get('lure')||'',notes:f.get('notes'),photos:[...(o?.photos||[]),...pp],weather:snap,weatherPending:!snap,at:o?.at||now()};await put('events',x);if(day&&snap){day.weatherSnapshots=[...(day.weatherSnapshots||[]),snap];await put('days',day)}$('#modal').close();render()};$('#edelete')?.addEventListener('click',async()=>{if(confirm('Eintrag wirklich löschen?')){await del('events',o.id);$('#modal').close();render()}})}'''
    s=s[:start]+new+s[end:]
    if helper not in s[:start]:
        s=s[:start]+helper+'\n'+s[start:]
p.write_text(s)
print('v0.5 event/weight patch normalized')
